 async function pageFor(query='',theme='light',width=1536,height=1000){
  const page=await browser.newPage({viewport:{width,height},locale:'ru-RU'});currentPage=page;
  page.on('pageerror',error=>runtimeErrors.push(error.message));
  await page.route('**/*',route=>route.request().url().startsWith(origin+'/')?route.continue():route.abort());
  await page.goto(`${origin}/ui-tests/filament-inventory.html?theme=${theme}&${query}`);
  return page;
 }
 const panel=page=>page.getByRole('region',{name:'Запас и расход пластика',exact:true});
 const form=page=>panel(page).locator('form');
 async function field(page,label){
  // Playwright's label text includes nested <option> text and optional hints.
  // Match the visible label prefix, then require exactly one real form control.
  const escaped=label.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  const control=form(page).getByLabel(new RegExp('^'+escaped));
  await control.waitFor();assert.equal(await control.count(),1,'Ambiguous inventory field: '+label);return control;
 }
 const material=(page,name)=>page.getByTestId('filament-material-'+name);
 const printer=(page,id)=>page.getByTestId('filament-printer-'+id);
 async function loaded(page){await panel(page).getByRole('button',{name:'Добавить пластик',exact:true}).waitFor()}
 async function state(page){return await page.evaluate(()=>window.__inventory())}
