 async function save(page,label='Сохранить'){await form(page).getByRole('button',{name:label,exact:true}).click();await form(page).waitFor({state:'detached'})}
 async function addStock(page,name,quantity,reserve){
  await panel(page).getByRole('button',{name:'Добавить пластик',exact:true}).click();
  await (await field(page,'Материал')).selectOption(name);
  await (await field(page,'Добавить на склад, кг')).fill(quantity);
  if(reserve!==undefined)await (await field(page,'Резерв, кг')).fill(reserve);
  await save(page);
 }
 async function writeoff(page,id,name,quantity){
