 async function noOverflow(page){
  const value=await page.evaluate(()=>({width:innerWidth,document:document.documentElement.scrollWidth,body:document.body.scrollWidth}));
  assert.ok(value.document<=value.width+1&&value.body<=value.width+1,'Filament UI overflows horizontally: '+JSON.stringify(value));
  const fields=await form(page).locator('input,select,button').evaluateAll(elements=>elements.filter(element=>{const s=getComputedStyle(element);return s.display!=='none'&&s.visibility!=='hidden'}).map(element=>{const b=element.getBoundingClientRect();return {left:b.left,right:b.right,label:element.getAttribute('aria-label')||element.textContent||element.tagName}}));
  for(const field of fields)assert.ok(field.left>=-.5&&field.right<=value.width+.5,'Unreachable inventory form control: '+JSON.stringify(field));
 }
 async function actualProductionParent(page){
  const classes=await panel(page).evaluate(element=>element.closest('.productionPanel.panel')?.className??'');
  assert.ok(classes.split(/\s+/).includes('productionPanel')&&classes.split(/\s+/).includes('panel'),'Field regression must run inside the actual production modal');return classes;
 }
 async function themedFields(page,kind){
  await actualProductionParent(page);
  await form(page).evaluate(element=>{if(element.contains(document.activeElement))document.activeElement.blur()});
  const proof=await form(page).evaluate((element,formKind)=>{
   const probe=document.createElement('span');probe.style.cssText='position:fixed;left:-10000px;top:0;background:var(--ui-surface);color:var(--ui-text);border:1px solid var(--ui-border-strong);outline:2px solid var(--ui-accent)';element.append(probe);
   const canonical=getComputedStyle(probe),expected={surface:canonical.backgroundColor,text:canonical.color,borderStrong:canonical.borderTopColor,accent:canonical.outlineColor,subtle:''};
   probe.style.color='var(--ui-subtle)';expected.subtle=getComputedStyle(probe).color;probe.remove();
   const fields=[...element.querySelectorAll('input,select')].map(control=>{
    const style=getComputedStyle(control),placeholder=control instanceof HTMLInputElement?control.placeholder:'';
    const row={tag:control.tagName.toLowerCase(),id:control.id,value:control.value,placeholder,background:style.backgroundColor,text:style.color,border:[style.borderTopColor,style.borderRightColor,style.borderBottomColor,style.borderLeftColor]};
    if(placeholder){const pseudo=getComputedStyle(control,'::placeholder');row.placeholderColor=pseudo.color;row.placeholderOpacity=pseudo.opacity;}
    return row;
   });
   return {form:formKind,parentClasses:element.closest('.productionPanel.panel')?.className??'',expected,fields};
  },kind);
  assert.ok(proof.fields.length>=3,'The actual production form has no fields');
  assert.ok(proof.expected.surface!=='rgba(0, 0, 0, 0)'&&proof.expected.text!==proof.expected.surface,'Theme tokens did not resolve to a readable surface');
  for(const input of proof.fields){
   assert.equal(input.background,proof.expected.surface,`${kind} ${input.id}: legacy production input background won over the theme`);
   assert.equal(input.text,proof.expected.text,`${kind} ${input.id}: input text differs from the theme`);
   for(const color of input.border)assert.equal(color,proof.expected.borderStrong,`${kind} ${input.id}: input border differs from the theme`);
   if(input.placeholder){assert.equal(input.placeholderColor,proof.expected.subtle,`${kind} ${input.id}: placeholder differs from the theme`);assert.equal(input.placeholderOpacity,'1',`${kind} ${input.id}: placeholder is faded`);}
  }
  assert.ok(proof.fields.some(input=>input.tag==='input')&&proof.fields.some(input=>input.tag==='select'),'Both input and select must be exercised inside production');
  return proof;
 }
 async function keyboardFieldEntry(page,kind,label,value,expectedAccent){
