  await material.focus();await page.keyboard.press('Tab');
  assert.equal(await target.evaluate(element=>element===document.activeElement),true,'Keyboard Tab must reach the quantity field');
  await page.keyboard.press('Control+A');await page.keyboard.type(value);
  assert.equal(await target.inputValue(),value,'Keyboard entry did not retain its value');
  const proof=await target.evaluate((element,formKind)=>{const style=getComputedStyle(element);return {form:formKind,tag:element.tagName.toLowerCase(),id:element.id,value:element.value,active:element===document.activeElement,focusVisible:element.matches(':focus-visible'),outlineStyle:style.outlineStyle,outlineWidth:parseFloat(style.outlineWidth),outlineColor:style.outlineColor,borderColor:style.borderTopColor}},kind);
  proof.expectedAccent=expectedAccent;
  assert.equal(proof.active,true);assert.equal(proof.focusVisible,true,'Keyboard focus must be visibly identified');
  assert.equal(proof.outlineStyle,'solid');assert.ok(proof.outlineWidth>=2,'Keyboard focus outline is missing or too thin');
  assert.equal(proof.outlineColor,expectedAccent,'Production focus outline lost the accent color');assert.equal(proof.borderColor,expectedAccent,'Production focus border lost the accent color');
  return proof;
 }
